Layer.GoOffMessageCommand:
%function(self)
			self:bounceend(0.3);
				if Choice1Selected then 
					self:x(0); 
					self:y(0); 
					self:diffuse(1,1,1,1);
					self:glowblink();
					self:effectperiod(0.2)
					self:zoom(2.2);
					self:sleep(0.5)
					self:accelerate(0.3)
					self:zoom(1.5)
					self:diffusealpha(0)
				else
					self:x(0);
					self:y(0);
					self:z(0);
					self:zoom(0);
				end
				self:sleep(5)
			end
